 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    from collections import Counter
    counts = Counter(v for row in grid for v in row)
    bg = counts.most_common(1)[0][0]
    comps = []
    seen = set()
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == bg or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            cells = []
            while stack:
                y, x = stack.pop()
                cells.append((y, x))
                for yy, xx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                    if 0 <= yy < h and 0 <= xx < w and grid[yy][xx] == color and (yy,xx) not in seen:
                        seen.add((yy,xx))
                        stack.append((yy,xx))
            comps.append((color, cells))

    # The reference color makes a connected L: one horizontal and one vertical arm.
    marker = None
    for color, cells in comps:
        if len(cells) < 5:
            continue
        rs = [r for r, c in cells]
        cs = [c for r, c in cells]
        if len(set(rs)) < 2 or len(set(cs)) < 2:
            continue
        # Verify all cells are on the two intersecting arms of an L.
        row_counts = Counter(rs)
        col_counts = Counter(cs)
        main_r = row_counts.most_common(1)[0][0]
        main_c = col_counts.most_common(1)[0][0]
        if all(r == main_r or c == main_c for r, c in cells):
            if row_counts[main_r] >= 3 and col_counts[main_c] >= 3:
                marker = color
                break

    if marker is None:
        return [row[:] for row in grid]

    # Recolor the color whose largest connected non-background object is biggest,
    # excluding the L marker.
    largest = {}
    for color, cells in comps:
        if color != marker:
            largest[color] = max(largest.get(color, 0), len(cells))
    if not largest:
        return [row[:] for row in grid]
    target = max(largest, key=largest.get)
    return [[marker if v == target else v for v in row] for row in grid]

if __name__ == '__main__':
    pass
