 "content": "def transform(grid):
    from collections import Counter
    h, w = len(grid), len(grid[0])
    counts = Counter(v for row in grid for v in row)
    bg = counts.most_common(1)[0][0]
    colors = set(counts) - {bg}

    # Each color's primary object is its largest four-connected component. The
    # color family that occurs in the most cells is the one recolored to the
    # marker color, found from the distinctive long straight bar objects.
    seen = set()
    comps = []
    for r in range(h):
        for c in range(w):
            v = grid[r][c]
            if v == bg or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            cells = []
            while stack:
                y, x = stack.pop()
                cells.append((y, x))
                for yy, xx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                    if 0 <= yy < h and 0 <= xx < w and grid[yy][xx] == v and (yy,xx) not in seen:
                        seen.add((yy,xx)); stack.append((yy,xx))
            comps.append((v, cells))

    # Marker is the color with a complete long horizontal/vertical bar of length
    # at least five; exclude it from recoloring.
    line_counts = Counter()
    for v, cells in comps:
        rs = [r for r, c in cells]; cs = [c for r, c in cells]
        if len(set(rs)) == 1 or len(set(cs)) == 1:
            if len(cells) >= 5:
                line_counts[v] += len(cells)
    marker = max(line_counts, key=line_counts.get) if line_counts else None
    if marker is None:
        return [row[:] for row in grid]

    totals = Counter()
    for v, cells in comps:
        if v != marker:
            totals[v] += len(cells)
    if not totals:
        return [row[:] for row in grid]
    # In scenes with a marker color sharing its family with other bars, choose
    # the strongest irregular-color family rather than the biggest bar family.
    irregular = Counter()
    for v, cells in comps:
        rs = {r for r, c in cells}; cs = {c for r, c in cells}
        if v != marker and len(rs) > 1 and len(cs) > 1:
            irregular[v] += len(cells)
    target = max(irregular, key=irregular.get) if irregular else max(totals, key=totals.get)
    return [[marker if x == target else x for x in row] for row in grid]
