 "content": "def transform(grid):
    # Determine the guide and target from distinctive objects:
    # the guide is an L-shaped component; its color replaces the dominant
    # repeated irregular object family.
    from collections import Counter
    h, w = len(grid), len(grid[0])
    counts = Counter(v for row in grid for v in row)
    bg = counts.most_common(1)[0][0]
    components = []
    seen = set()
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == bg or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            cells = []
            while stack:
                y, x = stack.pop()
                cells.append((y, x))
                for yy, xx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                    if 0 <= yy < h and 0 <= xx < w and grid[yy][xx] == color and (yy,xx) not in seen:
                        seen.add((yy,xx))
                        stack.append((yy,xx))
            components.append((color, cells))

    # Across the demonstrations, the output guide is the color forming the
    # straight L/bar reference; short L-shaped decoys exist, so select the
    # color whose L/bar objects are prominent and whose color is not dominant.
    # The transformed family has several chunky components, unlike the guide.
    color_stats = {}
    for color, cells in components:
        color_stats.setdefault(color, []).append(cells)
    candidates = []
    for color, parts in color_stats.items():
        # Candidate guide colors have a distinct straight / L-shaped object.
        guide_score = 0
        for cells in parts:
            rs = {r for r,c in cells}; cs = {c for r,c in cells}
            if len(cells) >= 3 and (len(rs) == 1 or len(cs) == 1):
                guide_score = max(guide_score, len(cells))
            if len(cells) >= 3 and len(rs) > 1 and len(cs) > 1:
                rowcnt = Counter(r for r,c in cells); colcnt = Counter(c for r,c in cells)
                mr = rowcnt.most_common(1)[0][0]; mc = colcnt.most_common(1)[0][0]
                if all(r == mr or c == mc for r,c in cells):
                    guide_score = max(guide_score, len(cells))
        if guide_score:
            candidates.append((guide_score, color))
    if not candidates:
        return [row[:] for row in grid]
    guide_color = max(candidates)[1]

    # Target is the color with the largest connected irregular object, among
    # colors distinct from the guide/background.
    target_candidates = []
    for color, parts in color_stats.items():
        if color == guide_color:
            continue
        irregular_sizes = []
        for cells in parts:
            rs = {r for r,c in cells}; cs = {c for r,c in cells}
            if len(rs) > 1 and len(cs) > 1:
                irregular_sizes.append(len(cells))
        if irregular_sizes:
            target_candidates.append((max(irregular_sizes), color))
    if not target_candidates:
        return [row[:] for row in grid]
    target_color = max(target_candidates)[1]
    return [[guide_color if v == target_color else v for v in row] for row in grid]

