    from collections import Counter
    h, w = len(grid), len(grid[0])
    counts = Counter(v for row in grid for v in row)
    bg = counts.most_common(1)[0][0]
    seen=set(); comps=[]
    for r in range(h):
        for c in range(w):
            v=grid[r][c]
            if v==bg or (r,c) in seen: continue
            stack=[(r,c)]; seen.add((r,c)); cells=[]
            while stack:
                y,x=stack.pop(); cells.append((y,x))
                for yy,xx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                    if 0<=yy<h and 0<=xx<w and grid[yy][xx]==v and (yy,xx) not in seen:
                        seen.add((yy,xx)); stack.append((yy,xx))
            comps.append((v,cells))

    # Detect prominent thin/straight guide component. Choose the color with the
    # most cells in straight components of length >= 5 (the output target color).
    straight_score=Counter()
    for v,cells in comps:
        rs={r for r,c in cells}; cs={c for r,c in cells}
        if len(cells)>=5 and (len(rs)==1 or len(cs)==1):
            straight_score[v] += len(cells)
    # The guide color has a distinctive L component; find it separately.
    guide_candidates=[]
    for v,cells in comps:
        if len(cells)<5: continue
        rc=Counter(r for r,c in cells); cc=Counter(c for r,c in cells)
        mr=rc.most_common(1)[0][0]; mc=cc.most_common(1)[0][0]
        if rc[mr]>=3 and cc[mc]>=3 and all(r==mr or c==mc for r,c in cells):
            guide_candidates.append((len(cells),v))
    if not guide_candidates:
        return [row[:] for row in grid]
    guide=max(guide_candidates)[1]

    # The recolored color is the one with the largest connected irregular object,
    # excluding the guide color. (Small L fragments are markers/decoys.)
    candidates=[]
    for v,cells in comps:
        if v==guide: continue
        rs={r for r,c in cells}; cs={c for r,c in cells}
        if len(rs)>1 and len(cs)>1:
            candidates.append((len(cells),v))
    if not candidates:
        return [row[:] for row in grid]
    target=max(candidates)[1]
    return [[guide if x==target else x for x in row] for row in grid]
