def _components(grid, background):
    h, w = len(grid), len(grid[0])
    seen = set()
    out = []
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == background or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            cells = []
            while stack:
                y, x = stack.pop()
                cells.append((y, x))
                for yy, xx in ((y - 1, x), (y + 1, x), (y, x - 1), (y, x + 1)):
                    if (0 <= yy < h and 0 <= xx < w and grid[yy][xx] == color
                            and (yy, xx) not in seen):
                        seen.add((yy, xx))
                        stack.append((yy, xx))
            out.append((color, cells))
    return out


def _shape(cells):
    min_r = min(r for r, c in cells)
    min_c = min(c for r, c in cells)
    return frozenset((r - min_r, c - min_c) for r, c in cells)


def _canonical(cells):
    pts = list(cells)
    forms = []
    for reflect in (False, True):
        for turns in range(4):
            transformed = []
            for r, c in pts:
                if reflect:
                    c = -c
                for _ in range(turns):
                    r, c = c, -r
                transformed.append((r, c))
            mr = min(r for r, c in transformed)
            mc = min(c for r, c in transformed)
            forms.append(tuple(sorted((r - mr, c - mc) for r, c in transformed)))
    return min(forms)


def transform(grid):
    counts = Counter(v for row in grid for v in row)
    background = counts.most_common(1)[0][0]
    components = _components(grid, background)

    # The guide color is the one containing the largest connected L-shaped bar.
    guides = []
    for color, cells in components:
        if len(cells) < 5:
            continue
        row_counts = Counter(r for r, c in cells)
        col_counts = Counter(c for r, c in cells)
        main_r = row_counts.most_common(1)[0][0]
        main_c = col_counts.most_common(1)[0][0]
        if (row_counts[main_r] >= 3 and col_counts[main_c] >= 3
                and all(r == main_r or c == main_c for r, c in cells)):
            guides.append((len(cells), color))
    guide_color = max(guides)[1] if guides else None

    # Find identical-shaped components of different colors. The recolored member
    # is the one belonging to the more substantial color family; the guide color
    # supplies its replacement color.
    shape_groups = {}
    for idx, (color, cells) in enumerate(components):
        shape_groups.setdefault(_canonical(cells), []).append((idx, color, cells))
    repeated = []
    for group in shape_groups.values():
        colors = {color for _, color, _ in group}
        if len(colors) > 1:
            repeated.append(group)
    if guide_color is not None and repeated:
        # Prefer the smallest repeated motif, which serves as the matching key.
        group = min(repeated, key=lambda g: (len(g[0][2]), -len(g)))
        family_sizes = Counter(v for row in grid for v in row if v != background)
        choices = [entry for entry in group if entry[1] != guide_color]
        if choices:
            idx, target_color, cells = max(choices, key=lambda e: (family_sizes[e[1]], len(e[2])))
            out = [row[:] for row in grid]
            for r, c in cells:
                out[r][c] = guide_color
            return out

    return [row[:] for row in grid]


