    counts = Counter(v for row in grid for v in row)
    bg = counts.most_common(1)[0][0]
    seen = set()
    comps = []
    for r in range(h):
        for c in range(w):
            v = grid[r][c]
            if v == bg or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            cells = []
            while stack:
                y, x = stack.pop()
                cells.append((y, x))
                for yy, xx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                    if 0 <= yy < h and 0 <= xx < w and grid[yy][xx] == v and (yy,xx) not in seen:
                        seen.add((yy,xx))
                        stack.append((yy,xx))
            comps.append((v, cells))

    # Recolor the unique diagonal/irregular instance of a repeated-color symbol
    # to the color of the large L-shaped guide component.
    guides = []
    for v, cells in comps:
        if len(cells) < 6:
            continue
        rc = Counter(r for r, c in cells)
        cc = Counter(c for r, c in cells)
        mr = rc.most_common(1)[0][0]
        mc = cc.most_common(1)[0][0]
        if rc[mr] >= 3 and cc[mc] >= 3 and all(r == mr or c == mc for r, c in cells):
            guides.append((len(cells), v))
    if not guides:
        return [row[:] for row in grid]
    guide = max(guides)[1]

    # Within each color, find components having a non-line silhouette. The
    # repeated motif is selected by its association with another same-shape
    # component; in the test the one-cell 6 components match the guide motif.
    # Select the smaller members of repeated shapes and recolor just those cells.
    def canonical(cells):
        forms = []
        for reflect in (False, True):
            for turns in range(4):
                pts = []
                for y, x in cells:
                    if reflect:
                        x = -x
                    for _ in range(turns):
                        y, x = x, -y
                    pts.append((y, x))
                my = min(y for y, x in pts)
                mx = min(x for y, x in pts)
                forms.append(tuple(sorted((y-my, x-mx) for y, x in pts)))
        return min(forms)

    by_shape = {}
    for v, cells in comps:
        if len(cells) >= 2:
            by_shape.setdefault(canonical(cells), []).append((v, cells))
    choices = []
    for group in by_shape.values():
        colors = {v for v, _ in group}
        if len(colors) > 1:
            for v, cells in group:
                if v != guide:
                    choices.append((len(cells), v, cells))
    if choices:
        _, _, cells = max(choices, key=lambda x: (x[0], x[1] == guide))
        out = [row[:] for row in grid]
        for r, c in cells:
            out[r][c] = guide
        return out

    # fallback: recolor largest non-guide component of the dominant non-bg color
    candidates = [(len(cells), v, cells) for v, cells in comps if v != guide]
    if candidates:
        _, _, cells = max(candidates)
        out = [row[:] for row in grid]
        for r, c in cells:
            out[r][c] = guide
        return out
    return [row[:] for row in grid]

